fact <- function(n) {
  if (n <= 1) return(1)
  n * fact(n - 1)
}

gcd <- function(a, b) {
  if (b == 0) a else gcd(b, a %% b)
}

is_prime <- function(n) {
  if (n < 2) return(FALSE)
  if (n < 4) return(TRUE)
  if (n %% 2 == 0) return(FALSE)
  i <- 3
  while (i * i <= n) {
    if (n %% i == 0) return(FALSE)
    i <- i + 2
  }
  TRUE
}

primes <- function(n) {
  is_p <- rep(TRUE, n)
  is_p[1] <- FALSE
  for (i in 2:floor(sqrt(n))) {
    if (is_p[i]) is_p[seq(i * i, n, by = i)] <- FALSE
  }
  which(is_p)
}

bisect <- function(f, a, b, tol = 1e-8) {
  while (b - a > tol) {
    m <- (a + b) / 2
    if (f(a) * f(m) <= 0) b <- m else a <- m
  }
  (a + b) / 2
}

horner <- function(coef, x) {
  res <- 0
  for (a in rev(coef)) res <- res * x + a
  res
}
